import * as THREE from 'three';
const damp=(from,to,speed,dt)=>THREE.MathUtils.damp(from,to,speed,dt);
export class AvatarMotionEngine{
 constructor(rig,element,options={}){this.rig=rig;this.element=element;this.options={lookX:.48,lookY:.24,bodyX:.15,...options};this.pointer={x:0,y:0,active:false};this.drag={active:false,startX:0,startYaw:0};this.bodyYaw=0;this.targetYaw=0;this.elapsed=0;this.nextGesture=4+Math.random()*3;this.gestureTime=0;this.gesture='';this.reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;this.handlers={move:e=>this.move(e),leave:()=>{if(!this.drag.active)this.pointer.active=false},down:e=>this.down(e),up:()=>this.up()};element.addEventListener('pointermove',this.handlers.move);element.addEventListener('pointerleave',this.handlers.leave);element.addEventListener('pointerdown',this.handlers.down);addEventListener('pointerup',this.handlers.up);element.style.touchAction='pan-y';}
 move(event){const rect=this.element.getBoundingClientRect();this.pointer.x=THREE.MathUtils.clamp((event.clientX-rect.left)/rect.width*2-1,-1,1);this.pointer.y=THREE.MathUtils.clamp(-((event.clientY-rect.top)/rect.height*2-1),-1,1);this.pointer.active=true;if(this.drag.active)this.targetYaw=THREE.MathUtils.clamp(this.drag.startYaw+(event.clientX-this.drag.startX)*.006,-1.05,1.05);}
 down(event){if(event.button!==0)return;this.drag={active:true,startX:event.clientX,startYaw:this.targetYaw};this.element.setPointerCapture?.(event.pointerId);}
 up(){this.drag.active=false;}
 trigger(name='greet'){this.gesture=name;this.gestureTime=0;}
 update(dt){this.elapsed+=dt;if(this.reduced)return;if(!this.drag.active)this.targetYaw=this.pointer.active?this.pointer.x*this.options.bodyX:damp(this.targetYaw,0,1.2,dt);this.bodyYaw=damp(this.bodyYaw,this.targetYaw,8,dt);this.rig.root.rotation.y=this.bodyYaw;const lookX=this.drag.active?0:(this.pointer.active?this.pointer.x*this.options.lookX:Math.sin(this.elapsed*.33)*.05),lookY=this.drag.active?0:(this.pointer.active?this.pointer.y*this.options.lookY:Math.sin(this.elapsed*.47)*.025);this.rig.head.rotation.y=damp(this.rig.head.rotation.y,lookX,10,dt);this.rig.head.rotation.x=damp(this.rig.head.rotation.x,-lookY,10,dt);const breathe=Math.sin(this.elapsed*1.45);this.rig.torso.scale.y=1+breathe*.012;this.rig.root.position.y=-1.66+Math.sin(this.elapsed*.72)*.035;this.rig.arms.forEach((arm,index)=>{arm.rotation.z=(index?-.025:.025)+Math.sin(this.elapsed*.8+index)*.015;});if(this.elapsed>this.nextGesture&&!this.drag.active){this.trigger(Math.random()>.45?'greet':'drift');this.nextGesture=this.elapsed+7+Math.random()*7;}if(this.gesture){this.gestureTime+=dt;const t=this.gestureTime;if(this.gesture==='greet'){const wave=Math.sin(t*10)*Math.sin(Math.min(1,t)*Math.PI);this.rig.arms[1].rotation.z=-.9-wave*.22;this.rig.arms[1].rotation.x=-.25;if(t>1.8){this.rig.arms[1].rotation.set(0,0,0);this.gesture='';}}else{this.rig.root.rotation.z=Math.sin(t*Math.PI)*.025;if(t>2){this.rig.root.rotation.z=0;this.gesture='';}}}const blink=(this.elapsed%5.2)>4.98?0.08:1;this.rig.eyes.forEach(eye=>eye.group.scale.y=blink);}
 destroy(){this.element.removeEventListener('pointermove',this.handlers.move);this.element.removeEventListener('pointerleave',this.handlers.leave);this.element.removeEventListener('pointerdown',this.handlers.down);removeEventListener('pointerup',this.handlers.up);}
}
